static const u16 *const sOverworldPals[PLAYER_LOOK_COUNT] = {sLook0_Ow, sLook1_Ow, sLook2_Ow, sLook3_Ow, sLook4_Ow};
static const u16 *const sFrontPals[PLAYER_LOOK_COUNT] = {sLook0_Front, sLook1_Front, sLook2_Front, sLook3_Front, sLook4_Front};
